  window.makeExamples = function(topic){
    const arr = TOPIC_EXAMPLES[topic.id];
    if (!arr) return [];
    return arr.map((e, i) => ({
      title: e.title,
      level: LEVELS[i] || 'Средний',
      code: e.code,
      output: e.output,
      explanation: `Уникальный пример #${i+1} темы «${topic.title}». Каждый пример раскрывает свой приём.`
    }));
  };
